"""Internal subprocess entry point. Task files are generated by the trusted local API."""

from __future__ import annotations

import json
import os
import sys
import traceback
from pathlib import Path

from .pipeline import DubbingPipeline
from .state import atomic_json
from .tasks import identifier


def execute(path: Path):
    task = json.loads(path.read_text())
    root = Path(task["root"])
    pipeline = DubbingPipeline(
        os.environ.get("ANIMODE_DEVICE", "cpu"), os.environ.get("ASR_MODEL", "large-v3")
    )

    def progress(value, message):
        task.update(progress=value, message=message)
        atomic_json(path, task)

    try:
        if task["action"] == "analyze":
            job = pipeline.analyze(
                task["video"], root / "projects", progress=progress, **task["options"]
            )
            task["project_id"] = Path(job["directory"]).name
        elif task["action"] == "render":
            manifest = root / "projects" / identifier(task["project_id"]) / "job.json"
            job = json.loads(manifest.read_text())
            options = dict(task["options"])
            expected = options.pop("expected_revision", job.get("revision", 0))
            if job.get("revision", 0) != expected:
                raise ValueError(
                    "Project changed after render was queued; resubmit the new revision."
                )
            pipeline.render(job, progress=progress, **options)
        else:
            raise ValueError("Unknown task action.")
        task.update(state="complete", progress=1, message="Ready")
    except Exception:
        traceback.print_exc()
        task.update(
            state="failed",
            message="Processing failed; inspect the local task log and project status.",
        )
    atomic_json(path, task)


if __name__ == "__main__":
    execute(Path(sys.argv[1]))
